COMMENT ON COLUMN sar_report.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN sar_report.created_at IS 'Creation time';
COMMENT ON COLUMN sar_report.created_by IS 'Principal that created the row';
COMMENT ON COLUMN sar_report.updated_at IS 'Last update time';
COMMENT ON COLUMN sar_report.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN sar_report.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN sar_report.aml_case_id IS 'Case (empty for threshold reports such as CTR)';
COMMENT ON COLUMN sar_report.report_type IS 'Report type';
COMMENT ON COLUMN sar_report.jurisdiction IS 'Filing jurisdiction';
COMMENT ON COLUMN sar_report.regulator IS 'FIU, e.g. FinCEN, NCA, FIC';
COMMENT ON COLUMN sar_report.status IS 'Status (changed only by actions)';
COMMENT ON COLUMN sar_report.narrative IS 'Final narrative';
COMMENT ON COLUMN sar_report.ai_draft_narrative IS 'AI-drafted narrative for the investigator to edit';
COMMENT ON COLUMN sar_report.suspicious_amount IS 'Amount involved';
COMMENT ON COLUMN sar_report.currency IS 'Currency';
COMMENT ON COLUMN sar_report.activity_start IS 'Suspicious activity start';
COMMENT ON COLUMN sar_report.activity_end IS 'Suspicious activity end';
COMMENT ON COLUMN sar_report.subjects IS 'Persons and entities reported ({name, type, id_number, country, role})';
COMMENT ON COLUMN sar_report.transactions IS 'Transactions reported ({transaction_id, date, amount, currency, from, to, description})';
COMMENT ON COLUMN sar_report.filing_deadline IS 'Regulatory deadline';
COMMENT ON COLUMN sar_report.filing_channel IS 'API, EXPORT or PORTAL';
COMMENT ON COLUMN sar_report.export_document_id IS 'goAML XML / FinCEN BSA XML file';
COMMENT ON COLUMN sar_report.prepared_by IS 'Preparer (submitter for approval)';
COMMENT ON COLUMN sar_report.approved_by IS 'MLRO approval';
COMMENT ON COLUMN sar_report.submitted_at IS 'Submission time';
COMMENT ON COLUMN sar_report.acknowledged_at IS 'FIU acknowledgement time';
COMMENT ON COLUMN sar_report.regulator_reference IS 'FIU reference number';
COMMENT ON COLUMN sar_report.rejection_reason IS 'FIU rejection reason';
COMMENT ON COLUMN sar_report.returned_by IS 'MLRO who last returned the report to DRAFT for rework';
COMMENT ON COLUMN sar_report.return_reason IS 'Why the MLRO returned the report';
COMMENT ON COLUMN sar_report.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN sar_report.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN sar_report.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN sar_report.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN sar_report.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_sar_report_tenant ON sar_report (tenant_id, created_at);
CREATE INDEX ix_sar_report_aml_case_id ON sar_report (aml_case_id);
CREATE INDEX ix_sar_report_export_document_id ON sar_report (export_document_id);
ALTER TABLE sar_report ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON sar_report USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_sar_report_touch BEFORE UPDATE ON sar_report FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium); relayed rows stay for the replay window.
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  published_at    timestamptz
);
COMMENT ON COLUMN outbox.published_at IS 'When the relay published the event (NULL = pending). Relayed rows are kept for the replay window (meridian.events.retention.window) and then purged (MR-GAME-DAY)';
CREATE INDEX ix_outbox_pending ON outbox (created_at, id) WHERE published_at IS NULL;
CREATE INDEX ix_outbox_published ON outbox (published_at) WHERE published_at IS NOT NULL;
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA aml_case TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA aml_case TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA aml_case GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
